package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"

	"github.com/gin-gonic/gin"
)

var failures int

func check(name string, got, want interface{}) {
	if fmt.Sprint(got) != fmt.Sprint(want) {
		failures++
		fmt.Printf("  FAIL %-28s got=%q want=%q\n", name, fmt.Sprint(got), fmt.Sprint(want))
	} else {
		fmt.Printf("  ok   %-28s = %q\n", name, fmt.Sprint(got))
	}
}

type result struct {
	status   int
	body     string
	fullPath string
	params   map[string]string
	panicMsg string
}

func do(e *gin.Engine, path string) (r result) {
	defer func() {
		if rec := recover(); rec != nil {
			r.panicMsg = fmt.Sprint(rec)
		}
	}()
	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, path, nil)
	e.ServeHTTP(w, req)
	r.status = w.Code
	r.body = w.Body.String()
	return
}

func doCapture(e *gin.Engine, path string) (r result) {
	defer func() {
		if rec := recover(); rec != nil {
			r.panicMsg = fmt.Sprint(rec)
		}
	}()
	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, path, nil)
	e.ServeHTTP(w, req)
	r.status = w.Code
	r.body = w.Body.String()
	return
}

func main() {
	gin.SetMode(gin.TestMode)

	// ---------------------------------------------------------------
	// Scenario 1: exact user report: catch-all route added at runtime
	// ---------------------------------------------------------------
	fmt.Println("== scenario 1: /test/:name/:last_name/*wild added at runtime ==")
	{
		e := gin.New()
		e.GET("/ping", func(c *gin.Context) { c.String(200, "pong") })

		r1 := do(e, "/test/john/smith/is/super/great")
		check("pre-registration status", r1.status, 404)
		check("pre-registration panic", r1.panicMsg, "")

		e.GET("/test/:name/:last_name/*wild", func(c *gin.Context) {
			c.JSON(200, gin.H{
				"name":      c.Param("name"),
				"last_name": c.Params.ByName("last_name"),
				"wild":      c.Param("wild"),
				"fullpath":  c.FullPath(),
			})
		})

		r2 := do(e, "/test/john/smith/is/super/great")
		check("post-registration panic", r2.panicMsg, "")
		check("post-registration status", r2.status, 200)
		check("body", r2.body, `{"fullpath":"/test/:name/:last_name/*wild","last_name":"smith","name":"john","wild":"is/super/great"}`)
	}

	// ---------------------------------------------------------------
	// Scenario 2: plain :param route added at runtime
	// ---------------------------------------------------------------
	fmt.Println("== scenario 2: /user/:id added at runtime ==")
	{
		e := gin.New()
		e.GET("/ping", func(c *gin.Context) { c.String(200, "pong") })
		r1 := do(e, "/user/42")
		check("pre-registration status", r1.status, 404)

		e.GET("/user/:id", func(c *gin.Context) {
			c.JSON(200, gin.H{"id": c.Param("id"), "fullpath": c.FullPath()})
		})
		r2 := do(e, "/user/42")
		check("post-registration panic", r2.panicMsg, "")
		check("post-registration status", r2.status, 200)
		check("body", r2.body, `{"fullpath":"/user/:id","id":"42"}`)
	}

	// ---------------------------------------------------------------
	// Scenario 3: maxParams growth (more params than any earlier route)
	// and maxSections growth (more sections than any earlier route)
	// ---------------------------------------------------------------
	fmt.Println("== scenario 3: maxParams/maxSections growth at runtime ==")
	{
		e := gin.New()
		e.GET("/ping", func(c *gin.Context) { c.String(200, "pong") })
		do(e, "/ping")

		// route with more params than anything registered before
		e.GET("/p/:a/:b/:c/:d", func(c *gin.Context) {
			c.JSON(200, gin.H{"a": c.Param("a"), "b": c.Param("b"), "c": c.Param("c"), "d": c.Param("d"), "fullpath": c.FullPath()})
		})
		r := do(e, "/p/1/2/3/4")
		check("maxParams panic", r.panicMsg, "")
		check("maxParams status", r.status, 200)
		check("maxParams body", r.body, `{"a":"1","b":"2","c":"3","d":"4","fullpath":"/p/:a/:b/:c/:d"}`)

		// route with more sections than anything registered before
		e.GET("/s/a/b/c/d/e/f/g/h", func(c *gin.Context) {
			c.JSON(200, gin.H{"fullpath": c.FullPath()})
		})
		r = do(e, "/s/a/b/c/d/e/f/g/h")
		check("maxSections panic", r.panicMsg, "")
		check("maxSections status", r.status, 200)
		check("maxSections body", r.body, `{"fullpath":"/s/a/b/c/d/e/f/g/h"}`)
	}

	// ---------------------------------------------------------------
	// Scenario 4: many params + many sections + catch-all, mixed
	// ---------------------------------------------------------------
	fmt.Println("== scenario 4: mixed growth, many runtime routes ==")
	{
		e := gin.New()
		e.GET("/ping", func(c *gin.Context) { c.String(200, "pong") })
		do(e, "/ping")
		e.GET("/x/:a", func(c *gin.Context) { c.String(200, c.Param("a")) })
		do(e, "/x/1")
		e.GET("/y/:a/:b/:c/:d/:e/:f/:g/h/i/j/k/l", func(c *gin.Context) {
			c.JSON(200, gin.H{"a": c.Param("a"), "g": c.Param("g"), "fullpath": c.FullPath()})
		})
		r := do(e, "/y/1/2/3/4/5/6/7/h/i/j/k/l")
		check("mixed panic", r.panicMsg, "")
		check("mixed status", r.status, 200)
		check("mixed body", r.body, `{"a":"1","fullpath":"/y/:a/:b/:c/:d/:e/:f/:g/h/i/j/k/l","g":"7"}`)

		e.GET("/z/:a/*rest", func(c *gin.Context) {
			c.JSON(200, gin.H{"a": c.Param("a"), "rest": c.Param("rest"), "fullpath": c.FullPath()})
		})
		r = do(e, "/z/hello/one/two/three")
		check("mixed catchall panic", r.panicMsg, "")
		check("mixed catchall status", r.status, 200)
		check("mixed catchall body", r.body, `{"a":"hello","fullpath":"/z/:a/*rest","rest":"one/two/three"}`)
	}

	// ---------------------------------------------------------------
	// Scenario 5: params must be identical to the up-front registration
	// ---------------------------------------------------------------
	fmt.Println("== scenario 5: runtime vs up-front equivalence ==")
	{
		handler := func(c *gin.Context) {
			c.JSON(200, gin.H{
				"name":      c.Param("name"),
				"last_name": c.Param("last_name"),
				"wild":      c.Param("wild"),
				"fullpath":  c.FullPath(),
			})
		}
		upfront := gin.New()
		upfront.GET("/test/:name/:last_name/*wild", handler)
		ru := do(upfront, "/test/john/smith/is/super/great")

		runtime := gin.New()
		runtime.GET("/ping", func(c *gin.Context) { c.String(200, "pong") })
		do(runtime, "/test/john/smith/is/super/great") // 404, allocates context
		runtime.GET("/test/:name/:last_name/*wild", handler)
		rr := do(runtime, "/test/john/smith/is/super/great")

		check("runtime panic", rr.panicMsg, "")
		check("runtime status", rr.status, ru.status)
		check("runtime body == upfront body", rr.body, ru.body)
	}

	// ---------------------------------------------------------------
	// Scenario 6: FullPath check for the user's exact report
	// ---------------------------------------------------------------
	fmt.Println("== scenario 6: FullPath ==")
	{
		e := gin.New()
		e.GET("/ping", func(c *gin.Context) { c.String(200, "pong") })
		do(e, "/test/john/smith/is/super/great")
		var gotFullPath string
		e.GET("/test/:name/:last_name/*wild", func(c *gin.Context) {
			gotFullPath = c.FullPath()
			c.String(200, "ok")
		})
		r := do(e, "/test/john/smith/is/super/great")
		check("panic", r.panicMsg, "")
		check("status", r.status, 200)
		check("FullPath", gotFullPath, "/test/:name/:last_name/*wild")
	}

	// ---------------------------------------------------------------
	// Scenario 7: route registered at runtime while a *stale* context
	// with 0 capacity is definitely in the pool; use a plain route with
	// a param plus a catch-all to hit both branches.
	// ---------------------------------------------------------------
	fmt.Println("== scenario 7: repeated runtime registrations ==")
	{
		e := gin.New()
		e.GET("/ping", func(c *gin.Context) { c.String(200, "pong") })
		do(e, "/ping")
		e.GET("/a/:p", func(c *gin.Context) { c.String(200, c.Param("p")) })
		r := do(e, "/a/v1")
		check("a panic", r.panicMsg, "")
		check("a body", r.body, "v1")
		e.GET("/b/:p/:q/*r", func(c *gin.Context) {
			c.String(200, c.Param("p")+"|"+c.Param("q")+"|"+c.Param("r"))
		})
		r = do(e, "/b/v2/v3/v4/v5")
		check("b panic", r.panicMsg, "")
		check("b body", r.body, "v2|v3|v4/v5")
		e.GET("/c/:p/:q/:r/:s/:t", func(c *gin.Context) {
			c.String(200, strings.Join([]string{c.Param("p"), c.Param("q"), c.Param("r"), c.Param("s"), c.Param("t")}, "|"))
